create table public.admin_users (id uuid default gen_random_uuid(), auth_user_id uuid, email text, full_name text, role text, extra_roles text, employee_id text, is_active boolean, notes text, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table public.audit_logs (id integer, action text, performed_by text, target_employee text, details text, created_at timestamp with time zone default now());
create table public.daily_sales (id uuid default gen_random_uuid(), sale_date date, total_walkin numeric, total_messenger numeric, total_reseller numeric, total_revenue numeric, total_cogs numeric, gross_profit numeric, notes text, encoded_by text, created_at timestamp with time zone default now(), cash_received numeric(12,2), gcash_received numeric(12,2), other_online_received numeric(12,2), unpaid_amount numeric(12,2));
create table public.pos_daily_donut_log (id bigint, outlet_id text, product_id text, business_date date, delivered_qty numeric, sold_qty numeric, expected_remaining numeric, actual_counted numeric, variance numeric, tracking_mode text, closed_at timestamp with time zone, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), starting_stock numeric);
create table public.pos_inventory_movements (id bigint, outlet_id text, product_id text, sku text, barcode text, product_name text, movement_type text, qty numeric(12,2), reference_no text, remarks text, created_by text, created_at timestamp with time zone default now());
create table public.pos_products (id text, sku text, barcode text, product_name text, category text, selling_price numeric(12,2), cost numeric(12,2), stock numeric(12,2), min_stock numeric(12,2), is_active boolean, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), outlet_id text, daily_tracking_mode text, standard_daily_qty numeric);
create table public.pos_sale_items (id bigint, sale_id text, receipt_no text, product_id text, sku text, barcode text, product_name text, category text, qty numeric(12,2), unit_price numeric(12,2), line_total numeric(12,2), created_at timestamp with time zone default now());
create table public.pos_sale_payments (id bigint, sale_id text, receipt_no text, method text, amount numeric, created_at timestamp with time zone default now());
create table public.pos_sales (id text, receipt_no text, outlet_id text, outlet_name text, cashier_id text, cashier_name text, business_date date, gross_total numeric(12,2), discount_total numeric(12,2), net_total numeric(12,2), payment_method text, cash_received numeric(12,2), change_amount numeric(12,2), status text, synced boolean, created_at timestamp with time zone default now(), voided_at timestamp with time zone, voided_by text, void_reason text, shift_id text, note text, sale_channel text, is_partial boolean, amount_paid numeric, balance_due numeric);
create table public.pos_shift_closings (id uuid default gen_random_uuid(), outlet_id text, business_date date, opening_cash numeric, cash_sales numeric, gcash_sales numeric, online_sales numeric, total_sales numeric, expected_cash numeric, actual_cash numeric, cash_variance numeric, transaction_count integer, closed_by text, remarks text, created_at timestamp with time zone default now(), shift_id text, verified_by text, verified_by_role text, updated_at timestamp with time zone default now());
create table public.pos_shifts (id text, outlet_id text, cashier_id text, cashier_name text, opened_at timestamp with time zone, closed_at timestamp with time zone, starting_cash numeric(10,2), expected_cash numeric(10,2), counted_cash numeric(10,2), variance numeric(10,2), status text, notes text);
